 if(!state.sound)return;
 try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const now=audioCtx.currentTime;[0,...(kind==='chime'?[.12,.24]:[])].forEach((offset,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.type='sine';o.frequency.setValueAtTime((kind==='chime'?[523,659,784][i]:440),now+offset);o.frequency.exponentialRampToValueAtTime(kind==='chime'?([523,659,784][i]*1.1):180,now+offset+.13);g.gain.setValueAtTime(.035,now+offset);g.gain.exponentialRampToValueAtTime(.001,now+offset+.17);o.start(now+offset);o.stop(now+offset+.18);});}catch(err){}
